package com.ticket.defender_core.application.service;

import com.ticket.defender_core.security.AdminRole;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.time.ZoneOffset;
import java.util.*;

/** Tenant/event-scoped read model. It never returns HMACs or S3 references. */
@Service
public class BulkLedgerTrack1BulkQueryService {
    private static final Set<AdminRole> ROLES=Set.of(AdminRole.TENANT_ADMIN,AdminRole.ANALYST,AdminRole.REVIEWER,AdminRole.APPROVER);
    private final CandidatePipelineAccess access; private final JdbcTemplate jdbc;
    public BulkLedgerTrack1BulkQueryService(CandidatePipelineAccess access,JdbcTemplate jdbc){this.access=access;this.jdbc=jdbc;}
    public List<Job> list(UUID eventId,UUID performanceId){var s=access.event(eventId,ROLES);return jdbc.query("select j.id,j.ledger_version_id,j.data_job_id,j.status,j.data_status,j.failure_code,j.algorithm_version,j.shared_signal_observations_status,j.purchase_limit_evaluations_status,j.created_at,j.updated_at,j.completed_at,p.policy_verification_status,p.quantity_data_status,p.data_completeness_reason,p.policy_id,p.policy_revision,p.policy_version from td_bulk_ledger_track1_bulk_jobs j left join td_bulk_ledger_track1_policy_snapshots p on p.job_id=j.id where j.tenant_id=? and j.event_id=? and j.performance_id=? order by j.created_at desc",(rs,n)->new Job(uuid(rs.getString(1)),uuid(rs.getString(2)),nullable(rs.getString(3)),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getString(8),rs.getString(9),rs.getTimestamp(10).toLocalDateTime().atOffset(ZoneOffset.UTC),rs.getTimestamp(11).toLocalDateTime().atOffset(ZoneOffset.UTC),rs.getTimestamp(12)==null?null:rs.getTimestamp(12).toLocalDateTime().atOffset(ZoneOffset.UTC),rs.getString(13),rs.getString(14),rs.getString(15),nullable(rs.getString(16)),(Integer)rs.getObject(17),rs.getString(18)),s.tenantId().toString(),eventId.toString(),performanceId.toString());}
    public Page clusters(UUID eventId,UUID performanceId,UUID jobId,int page,int size){if(page<0||size<1||size>100)throw new CaseApiException(HttpStatus.BAD_REQUEST,"INVALID_PAGE");Job j=find(eventId,performanceId,jobId);List<Cluster> rows=jdbc.query("select cluster_id,risk_score,member_count,json_length(payment_hashes_json),json_length(address_hashes_json),json_length(device_hashes_json),json_length(ip_hashes_json) from td_bulk_ledger_track1_bulk_clusters where job_id=? order by risk_score desc,cluster_id limit ? offset ?",(rs,n)->new Cluster(rs.getString(1),rs.getDouble(2),rs.getInt(3),rs.getInt(4),rs.getInt(5),rs.getInt(6),rs.getInt(7)),jobId.toString(),size+1,page*size);boolean more=rows.size()>size;if(more)rows=rows.subList(0,size);return new Page(j,rows,page,size,more);}
    public Members members(UUID eventId,UUID performanceId,UUID jobId,String clusterId,int page,int size){if(page<0||size<1||size>500||clusterId==null||clusterId.isBlank())throw new CaseApiException(HttpStatus.BAD_REQUEST,"INVALID_PAGE");find(eventId,performanceId,jobId);int count=jdbc.queryForObject("select count(*) from td_bulk_ledger_track1_bulk_clusters where job_id=? and cluster_id=?",Integer.class,jobId.toString(),clusterId);if(count!=1)throw new CaseApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND");List<Member> rows=jdbc.query("select account_reference_hmac,reservation_reference_hmac from td_bulk_ledger_track1_bulk_members where job_id=? and cluster_id=? order by account_reference_hmac,reservation_reference_hmac limit ? offset ?",(rs,n)->new Member(opaque(jobId,clusterId,rs.getString(1),rs.getString(2))),jobId.toString(),clusterId,size+1,page*size);boolean more=rows.size()>size;if(more)rows=rows.subList(0,size);return new Members(clusterId,rows,page,size,more);}
    public Page sharedSignals(UUID eventId,UUID performanceId,UUID jobId,int page,int size){valid(page,size);Job j=find(eventId,performanceId,jobId);List<SharedSignal> rows=jdbc.query("select observation_id,signal_type,distinct_account_count,scope_account_count,distinct_reservation_count,total_ticket_quantity,ticket_quantity_status,payment_shared_account_count,device_shared_account_count,ip_network_type,purchase_window_seconds,excluded_from_louvain from td_bulk_ledger_track1_bulk_shared_signal_observations where job_id=? and performance_id=? order by observation_id limit ? offset ?",(rs,n)->new SharedSignal(rs.getString(1),rs.getString(2),rs.getInt(3),rs.getInt(4),rs.getInt(5),(Long)rs.getObject(6),rs.getString(7),rs.getInt(8),rs.getInt(9),rs.getString(10),(Long)rs.getObject(11),rs.getBoolean(12)),jobId.toString(),performanceId.toString(),size+1,page*size);return page(j,rows,page,size);}
    public Page evaluations(UUID eventId,UUID performanceId,UUID jobId,int page,int size){valid(page,size);Job j=find(eventId,performanceId,jobId);List<Evaluation> rows=jdbc.query("select performance_id,evaluation_status,policy_version,expected_finding_count,findings_status from td_bulk_ledger_track1_bulk_limit_evaluations where job_id=? and performance_id=? order by performance_id limit ? offset ?",(rs,n)->new Evaluation(uuid(rs.getString(1)),rs.getString(2),rs.getString(3),rs.getInt(4),rs.getString(5)),jobId.toString(),performanceId.toString(),size+1,page*size);return page(j,rows,page,size);}
    public Page findings(UUID eventId,UUID performanceId,UUID jobId,int page,int size){valid(page,size);Job j=find(eventId,performanceId,jobId);int found=jdbc.queryForObject("select count(*) from td_bulk_ledger_track1_bulk_limit_evaluations where job_id=? and performance_id=?",Integer.class,jobId.toString(),performanceId.toString());if(found!=1)throw new CaseApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND");List<Finding> rows=jdbc.query("select account_reference_hmac,effective_ticket_quantity,max_tickets_per_account,policy_version from td_bulk_ledger_track1_bulk_limit_findings where job_id=? and performance_id=? order by account_reference_hmac limit ? offset ?",(rs,n)->{String account=rs.getString(1);List<Reservation> reservations=jdbc.query("select reservation_reference_hmac,effective_ticket_quantity from td_bulk_ledger_track1_bulk_limit_finding_reservations where job_id=? and performance_id=? and account_reference_hmac=? order by reservation_reference_hmac",(r,i)->new Reservation(opaque(jobId,performanceId.toString(),account,r.getString(1)),r.getLong(2)),jobId.toString(),performanceId.toString(),account);return new Finding(opaque(jobId,performanceId.toString(),account,"FINDING"),rs.getLong(2),rs.getInt(3),rs.getString(4),reservations);},jobId.toString(),performanceId.toString(),size+1,page*size);return page(j,rows,page,size);}
    private void valid(int page,int size){if(page<0||size<1||size>100)throw new CaseApiException(HttpStatus.BAD_REQUEST,"INVALID_PAGE");}
    private <T> Page page(Job job,List<T> rows,int page,int size){boolean more=rows.size()>size;if(more)rows=rows.subList(0,size);return new Page(job,rows,page,size,more);}
    private Job find(UUID event,UUID performance,UUID job){return list(event,performance).stream().filter(x->x.jobId().equals(job)).findFirst().orElseThrow(()->new CaseApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND"));}
    private static String opaque(UUID job,String cluster,String account,String reservation){return CandidatePipelineSupport.sha256("BL07_MEMBER",job.toString(),cluster,account,reservation).substring(0,24);}private static UUID uuid(String x){return UUID.fromString(x);}private static UUID nullable(String x){return x==null?null:uuid(x);}
    public record Job(UUID jobId,UUID ledgerVersionId,UUID dataJobId,String status,String dataStatus,String failureCode,String algorithmVersion,String sharedSignalObservationsStatus,String purchaseLimitEvaluationsStatus,java.time.OffsetDateTime createdAt,java.time.OffsetDateTime updatedAt,java.time.OffsetDateTime completedAt,String policyVerificationStatus,String quantityDataStatus,String dataCompletenessReason,UUID policyId,Integer policyRevision,String policyVersion){public boolean retryable(){return "RETRYABLE".equals(status)||"FAILED".equals(status);}} public record Cluster(String clusterId,double riskScore,int memberCount,int paymentSharedSignalCount,int addressSharedSignalCount,int deviceSharedSignalCount,int ipSharedSignalCount){} public record Member(String memberId){} public record SharedSignal(String observationId,String signalType,int distinctAccountCount,int scopeAccountCount,int distinctReservationCount,Long totalTicketQuantity,String ticketQuantityStatus,int paymentSharedAccountCount,int deviceSharedAccountCount,String ipNetworkType,Long purchaseWindowSeconds,boolean excludedFromLouvain){} public record Evaluation(UUID performanceId,String status,String policyVersion,int accountLimitFindingCount,String findingsCollectionStatus){} public record Finding(String accountId,long effectiveTicketQuantity,int maxTicketsPerAccount,String policyVersion,List<Reservation> reservationQuantities){} public record Reservation(String reservationId,long effectiveTicketQuantity){} public record Page(Job job,List<?> items,int page,int pageSize,boolean hasNext){} public record Members(String clusterId,List<Member> items,int page,int pageSize,boolean hasNext){}
}
